/**
 * Devuelve el SVG de un ícono.
 */
function it_icon( string $name, string $class = 'size-6' ): string {
	$paths = it_icon_paths();
	$d     = $paths[ $name ] ?? $paths['code'];

	return sprintf(
		'<svg class="%s" fill="none" stroke="currentColor" stroke-width="1.8" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path stroke-linecap="round" stroke-linejoin="round" d="%s"/></svg>',
		esc_attr( $class ),
		esc_attr( $d )
	);
}

/**
 * Devuelve el SVG de una red social (Instagram y TikTok se dibujan simples).
 */
function it_social_icon( string $network, string $class = 'size-5' ): string {
	if ( 'instagram' === $network ) {
		return sprintf( '<svg class="%s" fill="none" stroke="currentColor" stroke-width="2" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><circle cx="17.5" cy="6.5" r="1" fill="currentColor" stroke="none"/></svg>', esc_attr( $class ) );
	}
	if ( 'tiktok' === $network ) {
		return sprintf( '<svg class="%s" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M14 3v11.5a3.5 3.5 0 11-3.5-3.5M14 3c.5 2.5 2.5 4.5 5 5"/></svg>', esc_attr( $class ) );
	}
	$paths = it_social_paths();
	if ( empty( $paths[ $network ] ) ) {
		return it_icon( 'link', $class );
	}
	return sprintf( '<svg class="%s" fill="currentColor" viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="%s"/></svg>', esc_attr( $class ), esc_attr( $paths[ $network ] ) );
}
